sel=list(range(len(names)))
while len(sel)>1:
    best=None
    for k in sel:
        s=[q for q in sel if q!=k]
        cc=np.linalg.lstsq(X[:,s],dP_dt,rcond=None)[0]
        e=np.mean((dP_dt-X[:,s]@cc)**2)/np.var(dP_dt)
        if best is None or e<best[0]: best=(e,k)
